fn="""function daysTo(date){return Math.ceil((new Date(date+'T23:59:59')-new Date())/86400000)}function renderJourney(){const j=state.journey,cps=j.checkpoints,current=cps.find(c=>c.status==='current')||cps.find(c=>c.status!=='done')||cps[cps.length-1],days=Math.max(0,daysTo(state.deadline)),weeks=Math.max(1,days/7),remaining=Math.max(0,(+j.requiredHours||0)-(+j.actualHours||0)),capacity=Math.round(weeks*(+state.hours||0)*10)/10,pace=Math.round((remaining/weeks)*10)/10,forecastDays=Math.ceil((remaining/Math.max(.1,+state.hours||0))*7),forecastDate=new Date(Date.now()+forecastDays*86400000).toISOString().slice(0,10),gap=capacity-remaining,plan=Math.min(100,+state.planned||0),actual=Math.min(100,+state.progress||0),risk=gap<0?'Critical':actual+8<plan?'At Risk':'On Track';return `<div class="head"><div><div class="eyebrow">VISION BACKCAST / TIME FIRST</div><h1>Journey Map</h1><p class="lead">Visionから期限・勤務時間・Checkpoint・Issue Aを逆算します。</p></div></div><div class="grid"><section class="card s12 journeyhero journeyvision"><div><span class="pill blue">VISION</span><h2>${esc(state.vision)}</h2><p class="lead">現在地：${esc(current.code)}｜${esc(current.title)}　→　到達期限：${esc(state.deadline)}</p><div class="forecastbar" style="margin-top:18px"><div class="actual" style="width:${actual}%"></div><i class="plan" style="left:${plan}%"></i></div><p class="cpmeta">実績 ${actual}%　/　計画 ${plan}%　/　状態 ${risk}</p></div><aside class="timebox"><span>TIME BOUNDARY</span><b>${state.hours}h / week</b><small>時間外労働 0h</small><hr style="border:0;border-top:1px solid #ffffff2b;margin:16px 0"><small>残り ${days}日・必要 ${remaining}h</small></aside></section><section class="card s12"><div class="title">JOURNEY HEALTH</div><div class="metricgrid"><div class="jmetric">残り日数<b>${days}</b><small>days</small></div><div class="jmetric">必要ペース<b>${pace}h</b><small>per week</small></div><div class="jmetric">勤務内余力<b>${Math.round(gap)}h</b><small>capacity gap</small></div><div class="jmetric">到達予測<b style="font-size:19px">${forecastDate}</b><small>${forecastDate<=state.deadline?'期限内':'期限超過'}</small></div></div><div class="alert ${gap>=0?'gapgood':'gapbad'}" style="margin-top:14px">${gap>=0?`勤務時間内だけで成立します。残余キャパシティは約${Math.round(gap)}時間です。`:`現在のJourneyは勤務時間内では成立しません。約${Math.abs(Math.round(gap))}時間不足しています。Checkpointの順序・範囲・期限を再設計してください。`}</div></section><section class="card s12"><div class="title">BACKCASTED CHECKPOINTS</div><div class="timeline"><div class="road">${cps.map(c=>`<article class="cp ${c.status}"><div class="cpdot">${c.status==='done'?'✓':esc(c.code.replace('CP',''))}</div><div class="cpbody"><span class="pill ${c.type==='Critical'?'red':c.type==='Transfer'?'purple':'blue'}">${esc(c.type)}</span><h3>${esc(c.code)}｜${esc(c.title)}</h3><div class="cpmeta">期限 ${esc(c.date)}<br>必要 ${c.hours}h / 実績 ${c.actual}h<br>依存 ${esc(c.depends||'なし')}</div><div class="criteria"><b>到達条件</b><br>${esc(c.criteria||'未設定')}</div>${c.issue?`<div class="alert" style="margin-top:9px"><b>Issue</b><br>${esc(c.issue)}</div>`:''}</div></article>`).join('')}</div></div></section><section class="card s7"><div class="title">CURRENT CHECKPOINT / ISSUE A</div><h2>${esc(current.code)}｜${esc(current.title)}</h2><p class="lead">${esc(current.criteria)}</p><div class="issue" style="margin-top:14px"><span class="pill orange">ISSUE A</span><h3>${esc(current.issue||state.issue.title)}</h3><p class="lead">Vision・期限・現在地・次のCheckpointから決まる最重要ギャップ。</p></div><div class="criteria"><b>必要Evidence</b><br>${esc(current.evidence||'未設定')}</div></section><section class="card s5"><div class="title">SCHEDULE GAP</div><h2>${risk}</h2><div class="stats" style="grid-template-columns:1fr 1fr"><div class="stat">計画<b>${plan}%</b></div><div class="stat">実績<b>${actual}%</b></div></div><p class="lead" style="margin-top:12px">${actual<plan?`計画より${plan-actual}%遅れています。次のPracticeは現在CheckpointのEvidenceへ直接つなげます。`:'計画線上です。次のCheckpointへの条件転移を準備できます。'}</p></section><section class="card s12"><div class="title">JOURNEY UPDATE HISTORY</div>${j.history.length?j.history.slice(-8).reverse().map(h=>`<div class="historyline"><b>${esc(h.by)}</b>｜${esc(h.action)}｜${esc(h.at)}</div>`).join(''):'<p class="lead">まだJourney変更履歴はありません。</p>'}</section></div>`}"""
